<template>
  <div>
    <!-- Toggle Card -->
    <div class="settings-card settings-mb-4">
      <div class="settings-toggle-item">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('vertex_tax_integration') }}</span>
        </div>
        <div class="settings-toggle-actions">
          <subscription-dialog
            v-model="show_popup"
            :settings="settings"
            :settingType="vertex_tax_integration_setting"
            :appKey="vertex_tax"
            :onConfirm="handleSubscriptionConfirm"
          />
          <f-toggle size="xs"
            v-model="user_settings[vertex_tax_integration_setting]"
            @update:model-value="saveVertexTaxIntegration"
          />
        </div>
      </div>
    </div>

    <template v-if="user_settings[vertex_tax_integration_setting]">

      <!-- Connection Settings Card -->
      <div class="settings-card settings-mb-4">
        <div class="vertex-config-form">

          <!-- Base URL -->
          <div class="vertex-field-group">
            <label class="vertex-field-label">
              <q-icon name="language" size="16px" />
              {{ $t('base_url') }} <span class="text-red">*</span>
            </label>
            <q-input
              outlined
              dense
              class="s-field back-white"
              v-model="vertexConfig.base_url"
              placeholder="https://lsccom.na1.ondemand.vertexinc.com"
            />
            <span class="field-hint">{{ $t('vertex_base_url_hint') }}</span>
          </div>

          <!-- Client ID & Client Secret -->
          <div class="vertex-field-row--two-col">
            <div class="vertex-field-group">
              <label class="vertex-field-label">
                <q-icon name="vpn_key" size="16px" />
                {{ $t('client_id') }} <span class="text-red">*</span>
              </label>
              <q-input
                outlined
                dense
                class="s-field back-white"
                v-model="vertexConfig.client_id"
                :placeholder="$t('client_id')"
              />
            </div>
            <div class="vertex-field-group">
              <label class="vertex-field-label">
                <q-icon name="vpn_key" size="16px" />
                {{ $t('client_secret') }} <span class="text-red">*</span>
              </label>
              <q-input
                outlined
                dense
                class="s-field back-white"
                v-model="vertexConfig.client_secret"
                :placeholder="$t('client_secret')"
                type="text"
                :class="{ 'vertex-secret-mask': !showSecret }"
              >
                <template v-slot:append>
                  <q-icon
                    :name="showSecret ? 'visibility_off' : 'visibility'"
                    size="xs"
                    class="cursor-pointer"
                    @click="showSecret = !showSecret"
                  />
                </template>
              </q-input>
            </div>
          </div>

          <div class="vertex-actions">
            <f-btn appearance="cancel" :loading="testing" @click="testConnection">{{ $t('test_connection') }}</f-btn>
            <f-btn :loading="saving" @click="saveVertexConfig">{{ $t('save') }}</f-btn>
          </div>

        </div>
      </div>

      <!-- Tolerance Settings Card -->
      <div class="settings-card">
        <div class="row q-col-gutter-sm vertex-tolerance-row">
          <div class="col-3">
            <label class="vertex-field-label">
              <q-icon name="tune" size="16px" />
              {{ $t('variance_type') }}
            </label>
            <q-select
              outlined
              dense
              class="s-field back-white"
              v-model="user_settings[vertex_tax_variance_type]"
              :options="varianceTypeOptions"
              emit-value
              map-options
              @update:model-value="(val: any) => updatePreference(vertex_tax_variance_type, val)"
            />
          </div>
          <div class="col-3">
            <label class="vertex-field-label">
              <q-icon name="straighten" size="16px" />
              {{ $t('variance_threshold') }}
            </label>
            <q-input
              outlined
              dense
              type="number"
              class="s-field back-white"
              v-model.number="user_settings[vertex_tax_variance_threshold]"
              @update:model-value="(val: any) => updatePreference(vertex_tax_variance_threshold, val)"
            />
          </div>
          <div class="col-6">
            <label class="vertex-field-label">
              <q-icon name="play_circle_outline" size="16px" />
              {{ $t('verification_trigger') }}
            </label>
            <q-select
              outlined
              dense
              class="s-field back-white"
              v-model="user_settings[vertex_verification_trigger]"
              :options="verificationTriggerOptions"
              emit-value
              map-options
              @update:model-value="(val: any) => updatePreference(vertex_verification_trigger, val)"
            />
          </div>
        </div>
      </div>

    </template>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { CONSTANTS } from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import { vertexApiService } from 'src/services';
import { defineComponent, ref, reactive } from 'vue';
import encryptionUtil from 'src/utils/encryptionUtil';
import { useSettingStore, useSubscriptionStore } from 'src/store/main';
import subscriptionDialog from 'src/pages/Settings/Components/Subscription/SubscriptionDialog.vue';

export interface VertexTaxConfig {
  base_url: string;
  client_id: string;
  client_secret: string;
  grant_type: string;
  audience: string;
}

export default defineComponent({
  el: '#app',
  mixins: [encryptionUtil],
  components: {
    subscriptionDialog,
  },
  data() {
    return {
      vertex_tax_integration_setting: CONSTANTS.vertex_tax_integration_setting,
      vertex_tax_variance_threshold: CONSTANTS.vertex_tax_variance_threshold,
      vertex_tax_variance_type: CONSTANTS.vertex_tax_variance_type,
      vertex_verification_trigger: CONSTANTS.vertex_verification_trigger,
      showSecret: false,
      settings: {} as Record<string, any>,
      vertex_tax: CONSTANTS.vertex_tax,
    };
  },
  computed: {
    varianceTypeOptions() {
      return [
        { label: this.$t('percent'), value: 'percent' },
        { label: this.$t('fixed_amount'), value: 'fixed_amount' },
      ];
    },
    verificationTriggerOptions() {
      return [
        { label: this.$t('before_export'), value: 'before_export' },
        { label: this.$t('before_approval'), value: 'before_approval' },
      ];
    },
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    const vertexConfig = reactive<VertexTaxConfig>({
      base_url: '',
      client_id: '',
      client_secret: '',
      grant_type: 'client_credentials',
      audience: 'verx://migration-api',
    });

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      saving: ref(false),
      testing: ref(false),
      updateSetting,
      vertexConfig,
      credentialId: ref(''),
      show_popup: ref(false),
    };
  },
  methods: {
    async initView() {
      if(!this.user_settings[CONSTANTS.vertex_tax_integration_setting]) {
        return;
      }
      if (this.user_settings[CONSTANTS.vertex_tax_variance_threshold] === undefined) {
        this.user_settings[CONSTANTS.vertex_tax_variance_threshold] = 25;
      }
      if (!this.user_settings[CONSTANTS.vertex_tax_variance_type]) {
        this.user_settings[CONSTANTS.vertex_tax_variance_type] = 'fixed_amount';
      }
      if (!this.user_settings[CONSTANTS.vertex_verification_trigger]) {
        this.user_settings[CONSTANTS.vertex_verification_trigger] = 'before_export';
      }
      await this.loadVertexConfig();
    },
    async loadVertexConfig() {
      try {
        this.loading = true;
        const config = await vertexApiService.getCredentials();
        if (config && config.id) {
          this.credentialId = config.id;
          this.vertexConfig.base_url = config.url;
          this.vertexConfig.client_id = config.client_id;
          this.vertexConfig.client_secret = config.client_secret ? this.decryptPassword(config.client_secret) : '';
          this.vertexConfig.grant_type = config.grant_type;
          this.vertexConfig.audience = config.audience;
        }
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.loading = false;
      }
    },
    async updatePreference(key: string, value: any) {
      try {
        await this.updateSetting(key, value);
        if (key === CONSTANTS.vertex_tax_integration_setting) {
          this.initView();
        }
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      }
    },
    // async updatedVertexTaxIntegrationSetting(value: any) {
    //   if (value) {
    //     this.user_settings[vertex_tax_integration_setting] = false;
    //     this.show_popup = true;
    //   } else {
    //     try {
    //       await this.updateSetting(vertex_tax_integration_setting, value);
    //       notify.success(this.$t('save_successfully'));
    //     } catch (error: any) {
    //       const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
    //       notify.error(msg);
    //       logError(error);
    //     }
    //   }
    // },
    saveVertexTaxIntegration(value: any) {
      if (value) {
        this.user_settings[this.vertex_tax_integration_setting] = false;
        this.show_popup = true;
      } else {
        this.handleSubscriptionConfirm(value);
      }
    },
    async handleSubscriptionConfirm(value: any) {
      await useSubscriptionStore().saveSubscriptionChange(
        value,
        this.vertex_tax,
        this.updateSetting,
      );
      if (value) {
        await this.initView();
      }
    },
    preparePayload() {
      return {
        url: this.vertexConfig.base_url,
        client_id: this.vertexConfig.client_id,
        client_secret: this.encryptPassword(this.vertexConfig.client_secret),
        grant_type: this.vertexConfig.grant_type,
        audience: this.vertexConfig.audience,
      };
    },
    validateRequiredFields(): boolean {
      if (!this.vertexConfig.base_url || !this.vertexConfig.client_id || !this.vertexConfig.client_secret) {
        notify.error(this.$t('MISSING_FIELD'));
        return false;
      }
      return true;
    },
    async saveVertexConfig() {
      if (!this.validateRequiredFields()) return;
      try {
        this.saving = true;
        const payload = this.preparePayload();
        if (this.credentialId) {
          await vertexApiService.updateCredentials(this.credentialId, payload);
        } else {
          const result = await vertexApiService.createCredentials(payload);
          if (result && result.id) {
            this.credentialId = result.id;
          }
        }
        notify.success(this.$t('save_successfully'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.saving = false;
      }
    },
    async testConnection() {
      if (!this.validateRequiredFields()) return;
      try {
        this.testing = true;
        const response = await vertexApiService.testCredentials(this.preparePayload());
        if (!response.success) {
          throw { message: response.message || response.detail };
        }
        notify.success(this.$t('test_connection_success'));
      } catch (error: any) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
      } finally {
        this.testing = false;
      }
    },
  },
});
</script>

