<template>
  <div class="page-container page-height-limit">
    <div class="settings-page-content">

      <!-- No results message -->
      <div v-if="searchQuery && !hasAnyMatch" class="no-results-message text-center q-pa-xl">
        <q-icon name="search_off" size="48px" color="grey-5" />
        <p class="q-mt-md text-grey-6">{{ $t('no_results_found') || 'No matching settings found' }}</p>
      </div>

      <!-- PO Settings Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('poSettings')"
        v-model="expandedSections.poSettings"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('poSettings') }"
        icon="mdi:cart"
        :title="$t('po_settings')"
        :subtitle="$t('po_matching_and_validation')"
        bodyClass=""
      >
        <PO />
      </DocbitsAccordionPanel>

      <!-- Auto Accounting Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('autoAccounting')"
        v-model="expandedSections.autoAccounting"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('autoAccounting') }"
        icon="mdi:bank"
        :title="$t('auto_accounting')"
        :subtitle="$t('automatic_accounting_configuration')"
        bodyClass=""
      >
        <Accounting />
      </DocbitsAccordionPanel>

      <!-- Vertex Tax Integration Section -->
      <DocbitsAccordionPanel
        v-show="isSectionVisible('vertexTax')"
        v-model="expandedSections.vertexTax"
        :class="{ 'section-dimmed': searchQuery && !isSectionMatched('vertexTax') }"
        icon="mdi:receipt-text"
        :title="$t('vertex_tax_integration')"
        :subtitle="$t('vertex_tax_integration_configuration')"
        bodyClass=""
      >
        <VertexTaxIntegration />
      </DocbitsAccordionPanel>

    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { useSettingStore } from 'src/store/main';
import { useAccordionSearch, type SectionSearchEntry } from 'src/utils/useAccordionSearch';
import PO from 'src/pages/Settings/Components/Modules/PO.vue';
import Accounting from 'src/pages/Settings/Components/Modules/Accounting.vue';
import VertexTaxIntegration from 'src/pages/Settings/Components/Modules/VertexTaxIntegration.vue';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';

const SEARCH_REGISTRY: Record<string, SectionSearchEntry> = {
  poSettings: {
    titleKeys: ['po_settings', 'po_matching_and_validation'],
    childKeys: [
      'po_auto_match_and_export',
      'purchase_order_dashboard',
      'po_shipment_order',
      'shipment_order_dashboard',
    ],
  },
  autoAccounting: {
    titleKeys: ['auto_accounting', 'automatic_accounting_configuration'],
    childKeys: [
      'auto_accounting',
      'accounts',
      'dimension_range_dropdown',
      'dimension_general_dropdown',
      'dimension_list_name',
      'po_account_list_name',
    ],
  },
  vertexTax: {
    titleKeys: ['vertex_tax_integration', 'vertex_tax_integration_configuration'],
    childKeys: ['vertex_tax_integration'],
  },
};

const SECTION_DEFAULTS: Record<string, boolean> = {
  poSettings: true,
  autoAccounting: false,
  vertexTax: false,
};

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  watch: {
    loading_settings: {
      handler: function (newVal) {
        if (newVal) {
          this.showLoading();
        }
      },
    },
    $route() {
      this.scrollToHash();
    },
  },
  components: {
    PO,
    Accounting,
    VertexTaxIntegration,
    DocbitsAccordionPanel,
  },
  mounted: function () {
    this.startSettingsFetch();
    this.scrollToHash();
  },
  methods: {
    scrollToHash() {
      if (this.$route.hash) {
        this.$nextTick(() => {
          setTimeout(() => {
            const element = document.getElementById(
              this.$route.hash.substring(1),
            );
            if (element) {
              element.scrollIntoView({ behavior: 'smooth' });
            }
          }, 100);
        });
      }
    },

    onSearch(searchItem: string) {
      this.handleSearch(searchItem, this.$t);
    },
  },

  setup() {
    const settings_store = useSettingStore();
    const { startSettingsFetch, loading_settings } = settings_store;
    const accordionSearch = useAccordionSearch(SEARCH_REGISTRY, SECTION_DEFAULTS);

    return {
      startSettingsFetch,
      loading_settings,
      ...accordionSearch,
    };
  },
});
</script>

<style lang="scss" scoped>
.section-dimmed {
  opacity: 0.4;
  pointer-events: none;
  transition: opacity 0.3s ease;
}

.no-results-message {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 200px;
}
</style>
