<template>
  <div class="settings-card">
    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('auto_accounting') }}
          <q-icon name="info" class="cursor-pointer q-ml-xs" color="primary" size="xs">
            <q-tooltip>{{ $t('invoice_only_feature') }}</q-tooltip>
          </q-icon>
        </span>
      </div>
      <div class="settings-toggle-selects accounting-select">
        <q-select
          outlined
          dense
          class="s-field back-white"
          v-model="user_settings[auto_accounting_types_setting]"
          :options="accounting_export_types"
          :label="$t('type')"
          @update:model-value="(val: any) => { saveSettings(auto_accounting_types_setting, val); }"
          emit-value
          map-options
        />
      </div>
      <div class="settings-toggle-actions accounting-toggle">
        <f-toggle size="xs"
          v-model="user_settings[auto_accounting_setting]"
          @update:model-value="(val: any) => { saveSettings(auto_accounting_setting, val); }"
        />
      </div>
    </div>

    <template v-if="user_settings[auto_accounting_types_setting] !== '' && user_settings[auto_accounting_setting] === true">
      <div class="settings-toggle-item-with-selects">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('accounts') }}</span>
        </div>
        <div class="settings-toggle-selects accounting-select">
          <q-select
            outlined
            dense
            class="s-field back-white"
            v-model="user_settings[auto_accounting_acc_list_name_setting]"
            :options="data_types"
            :loading="!data_types_loaded"
            :label="$t('select_account_name')"
            @update:model-value="(val: any) => { saveSettings(auto_accounting_acc_list_name_setting, val); }"
            emit-value
            map-options
          />
        </div>
        <div class="settings-toggle-actions accounting-toggle"></div>
      </div>

      <div class="settings-toggle-item-with-selects">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('dimension_range_dropdown') }}</span>
        </div>
        <div class="settings-toggle-selects accounting-select">
          <q-select
            outlined
            dense
            class="s-field back-white"
            v-model="user_settings[auto_accounting_dimensions_options_setting]"
            :options="data_types"
            :loading="!data_types_loaded"
            :label="$t('select_dimension')"
            @update:model-value="(val: any) => { saveSettings(auto_accounting_dimensions_options_setting, val); }"
            emit-value
            map-options
            clearable
          />
        </div>
        <div class="settings-toggle-actions accounting-toggle"></div>
      </div>

      <div class="settings-toggle-item-with-selects" v-if="user_settings[auto_accounting_types_setting] == 'm3'">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('dimension_general_dropdown') }}</span>
        </div>
        <div class="settings-toggle-selects accounting-select">
          <q-select
            outlined
            dense
            class="s-field back-white"
            v-model="user_settings[dimension_general_dropdown_accounting]"
            :options="data_types"
            :loading="!data_types_loaded"
            :label="$t('select_general_dimension')"
            @update:model-value="(val: any) => { saveSettings(dimension_general_dropdown_accounting, val); }"
            emit-value
            map-options
            clearable
          />
        </div>
        <div class="settings-toggle-actions accounting-toggle"></div>
      </div>

      <div class="settings-toggle-item-with-selects" v-if="user_settings[auto_accounting_types_setting] == 'ln'">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('dimension_list_name') }}</span>
        </div>
        <div class="settings-toggle-selects accounting-select">
          <q-select
            outlined
            dense
            class="s-field back-white"
            v-model="user_settings[auto_accounting_dimensions_list_setting]"
            :options="data_types"
            :loading="!data_types_loaded"
            :label="$t('select_dimension')"
            @update:model-value="(val: any) => { saveSettings(auto_accounting_dimensions_list_setting, val); }"
            emit-value
            map-options
          />
        </div>
        <div class="settings-toggle-actions accounting-toggle"></div>
      </div>

      <div class="settings-toggle-item-with-selects" v-if="user_settings[auto_accounting_types_setting] == 'm3'">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('po_account_list_name') }}</span>
        </div>
        <div class="settings-toggle-selects accounting-select">
          <q-select
            outlined
            dense
            class="s-field back-white"
            v-model="user_settings[auto_accounting_po_acc_list_name_setting]"
            :options="data_types"
            :loading="!data_types_loaded"
            :label="$t('select_po_account')"
            @update:model-value="(val: any) => { saveSettings(auto_accounting_po_acc_list_name_setting, val); }"
            emit-value
            map-options
          />
        </div>
        <div class="settings-toggle-actions accounting-toggle"></div>
      </div>

      <div class="settings-toggle-item-with-selects">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">
            {{ $t('auto_accounting_reset_on_change_label') }}
            <q-icon name="info" class="cursor-pointer q-ml-xs" color="primary" size="xs">
              <q-tooltip>{{ $t('auto_accounting_reset_on_change_tooltip') }}</q-tooltip>
            </q-icon>
          </span>
        </div>
        <div class="settings-toggle-selects accounting-select"></div>
        <div class="settings-toggle-actions accounting-toggle">
          <f-toggle size="xs"
            v-model="user_settings[auto_accounting_reset_data_on_change_setting]"
            @update:model-value="(val: any) => { saveSettings(auto_accounting_reset_data_on_change_setting, val); }"
          />
        </div>
      </div>
    </template>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { isUndefinedOrNull, isEmptyString } from 'src/utils/general';
import {
  useDropdownStore,
  useMasterDataLookupStore,
  useSettingStore,
} from 'src/store/main';
import {
  auto_accounting_setting,
  auto_accounting_reset_data_on_change_setting,
  auto_accounting_types_setting,
  auto_accounting_acc_list_name_setting,
  auto_accounting_po_acc_list_name_setting,
  auto_accounting_dimensions_list_setting,
  auto_accounting_dimensions_options_setting,
  dimension_general_dropdown_accounting,
} from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  components: {},
  data() {
    return {
      auto_accounting_setting,
      auto_accounting_reset_data_on_change_setting,
      auto_accounting_types_setting,
      auto_accounting_acc_list_name_setting,
      auto_accounting_dimensions_list_setting,
      auto_accounting_po_acc_list_name_setting,
      auto_accounting_dimensions_options_setting,
      dimension_general_dropdown_accounting,
      isUndefinedOrNull,
      isEmptyString,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        // this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  computed: {},
  methods: {
    initView() {
      this.initSettings();

      this.getDataSetTypes(false);
    },
    initSettings() {
      if (!this.user_settings[this.auto_accounting_types_setting]) {
        this.user_settings[this.auto_accounting_types_setting] = 'ln';
      }

      if (!this.user_settings[this.auto_accounting_setting]) {
        this.user_settings[this.auto_accounting_setting] = false;
      }

      if (!this.user_settings[this.auto_accounting_reset_data_on_change_setting]) {
        this.user_settings[this.auto_accounting_reset_data_on_change_setting] = false;
      }

      if (!this.user_settings[this.auto_accounting_acc_list_name_setting]) {
        this.user_settings[this.auto_accounting_acc_list_name_setting] = '';
      }

      if (!this.user_settings[this.auto_accounting_dimensions_list_setting]) {
        this.user_settings[this.auto_accounting_dimensions_list_setting] = '';
      }

      if (
        !this.user_settings[this.auto_accounting_dimensions_options_setting]
      ) {
        this.user_settings[this.auto_accounting_dimensions_options_setting] =
          '';
      }

      if (!this.user_settings[this.dimension_general_dropdown_accounting]) {
        this.user_settings[this.dimension_general_dropdown_accounting] = '';
      }

      if (!this.user_settings[this.auto_accounting_po_acc_list_name_setting]) {
        this.user_settings[this.auto_accounting_po_acc_list_name_setting] = '';
      }
    },

    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    const dropdown_store = useDropdownStore();
    const { accounting_export_types } = storeToRefs(dropdown_store);

    const master_data_lookup_store = useMasterDataLookupStore();
    const { getDataSetTypes } = master_data_lookup_store;
    const { data_types, data_types_loaded } = storeToRefs(
      master_data_lookup_store,
    );

    return {
      data_types,
      data_types_loaded,
      getDataSetTypes,
      updateSetting,
      accounting_export_types,
      user_settings,
      loading_settings,
      loading: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped>
.accounting-select {
  width: 25%;
  min-width: 200px;

  :deep(.q-field),
  :deep(.q-select) {
    width: 100% !important;
  }
}

.accounting-toggle {
  width: 50px;
  min-width: 50px;
  justify-content: flex-end;
}
</style>
