<template>
  <div class="settings-card">
    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('po_auto_match_and_export') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[po_auto_match_and_export]"
          @update:model-value="(val: any) => { saveSettings(po_auto_match_and_export, val); }"
        />
      </div>
    </div>

    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('purchase_order_dashboard') }}</span>
      </div>
      <div class="settings-toggle-selects" v-if="user_settings[po_dashboard]">
        <q-input
          dense
          outlined
          readonly
          class="s-field back-white"
          v-model="po_date_str"
          :label="$t('po_date_limit')"
        >
          <template v-slot:append>
            <q-icon name="event" class="cursor-pointer">
              <q-popup-proxy
                cover
                transition-show="scale"
                transition-hide="scale"
              >
                <q-date
                  v-model="po_date"
                  :mask="date_pattern"
                  :format="date_pattern"
                  @update:model-value="formatPOLimitDate"
                >
                  <div class="row items-center justify-end">
                    <q-btn
                      :label="$t('save')"
                      @click="saveSettings(po_date_limit, po_date)"
                      color="primary"
                      flat
                      v-close-popup
                    />
                    <q-btn
                      :label="$t('close')"
                      color="primary"
                      flat
                      v-close-popup
                    />
                  </div>
                </q-date>
              </q-popup-proxy>
            </q-icon>
            <q-icon name="info" class="cursor-pointer q-ml-xs" color="primary" size="xs">
              <q-tooltip>{{ $t('po_dashboard_filter_date') }}</q-tooltip>
            </q-icon>
          </template>
        </q-input>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[po_dashboard]"
          @update:model-value="(val: any) => { saveSettings(po_dashboard, val); }"
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('po_shipment_order') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[po_shipment_order]"
          @update:model-value="(val: any) => { saveSettings(po_shipment_order, val); }"
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('shipment_order_dashboard') }}</span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[shipment_order_dashboard]"
          @update:model-value="(val: any) => { saveSettings(shipment_order_dashboard, val); }"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSettingStore } from 'src/store/main';
import { CONSTANTS } from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
import dateUtils from 'src/utils/date';
export default defineComponent({
  el: '#app',
  mixins: [dateUtils],
  props: ['showSpinner'],
  components: {},
  data() {
    return {
      po_auto_match_and_export: CONSTANTS.po_auto_match_and_export,
      shipment_order_dashboard: CONSTANTS.shipment_order_dashboard,
      po_shipment_order: CONSTANTS.po_shipment_order,
      po_dashboard: CONSTANTS.po_dashboard,
      po_date_limit: CONSTANTS.po_date_limit,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.initView();
      },
    },
  },
  mounted: function () {
    this.initView();
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      loading_settings,
      loading: ref(false),
      updateSetting,
      po_date: ref(''),
      po_date_str: ref(''),
      date_pattern: ref(''),
    };
  },
  methods: {
    initView() {
      if (!this.user_settings[this.po_auto_match_and_export]) {
        this.user_settings[this.po_auto_match_and_export] = false;
      }

      if (!this.user_settings[this.po_dashboard]) {
        this.user_settings[this.po_dashboard] = false;
      }

      if (!this.user_settings[this.shipment_order_dashboard]) {
        this.user_settings[this.shipment_order_dashboard] = false;
      }

      if (!this.user_settings[this.po_shipment_order]) {
        this.user_settings[this.po_shipment_order] = false;
      }

      this.po_date = this.user_settings[this.po_date_limit] || '';
      this.date_pattern = this.getDatePattern();
      this.formatPOLimitDate();
    },

    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }
      try {
        this.loading = true;
        if (key == this.po_date_limit) {
          value = this.formatDateToUniversal(value);
        }
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    formatPOLimitDate() {
      const date = this.formatDateToUniversal(this.po_date);
      this.po_date_str = this.po_date
        ? this.formatDateAccordingToPreference(date, true)
        : '';
    },
  },
});
</script>

<style lang="scss" scoped></style>
